// 把多段文本各自按 wrap 的规则折行，段与段之间用一个空行分隔。
// 空段保留为一个空行；空数组结果为空字符串。
export function joinFitted(paragraphs, maxWidth) {
  const fitted = paragraphs.map((p) => {
    const lines = wrap(p, maxWidth);
    return lines.length === 0 ? [""] : lines;
  });
  const out = [];
  fitted.forEach((lines, i) => {
    if (i > 0) out.push("");
    out.push(...lines);
  });
  return out.join("\n");
}

